args <- commandArgs(trailingOnly=TRUE); if(!length(args)) stop("Usage: Rscript scripts/inspect_smoke_download.R <downloaded-path>")
invisible(lapply(list.files("R",pattern="\\.R$",full.names=TRUE),source)); path<-normalizePath(args[[1]],mustWork=TRUE); fmt<-detect_download_format(path); cat("actual file type:",fmt,"\n"); cat("NetCDF readable with ncdf4: ",requireNamespace("ncdf4",quietly=TRUE),"\n",sep=""); md<-tryCatch(inspect_netcdf_ncdf4(path),error=function(e){cat("ncdf4 diagnostic:",conditionMessage(e),"\n");NULL}); terra_ok<-tryCatch({terra::rast(path);TRUE},error=function(e){cat("terra/GDAL diagnostic:",conditionMessage(e),"\n");FALSE}); cat("NetCDF readable with terra/GDAL: ",terra_ok,"\n",sep=""); if(!is.null(md)){ v<-select_era5_temperature_variable(md); cat("variables:",paste(names(md$variables),collapse=", "),"\ndimensions:",paste(names(md$dimensions),collapse=", "),"\ntemperature variable:",v,"\ntemperature units:",md$variables[[v]]$units,"\ntemperature dimensions:",paste(md$variables[[v]]$dimensions,collapse=", "),"\ndecoded dates:",paste(md$decoded_dates,collapse=", "),"\nreader recommended: ncdf4\n") }
